-- Frozen WordPress inventory only; no CMS article is imported or assigned here.
-- Source: wordpress-export.json (2026-08-10).
CREATE TABLE legacy_blog_sources (
  source_id INTEGER PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  published_at TEXT NOT NULL,
  source_sha256 TEXT NOT NULL CHECK(length(source_sha256) = 64)
);
CREATE TABLE legacy_blog_links (
  content_id TEXT PRIMARY KEY REFERENCES content_drafts(id),
  source_id INTEGER NOT NULL UNIQUE REFERENCES legacy_blog_sources(source_id),
  linked_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- A trusted migration links only an unpublished blog whose draft uses the exact old URL.
CREATE TRIGGER validate_legacy_blog_link BEFORE INSERT ON legacy_blog_links BEGIN
  SELECT CASE WHEN NOT EXISTS (
    SELECT 1 FROM content_drafts d JOIN legacy_blog_sources s ON s.source_id = NEW.source_id
    JOIN event_url_owners u ON u.slug = 'local-blog/' || s.slug
    WHERE d.id = NEW.content_id AND d.type = 'blog'
      AND json_extract(d.payload, '$.slug') = s.slug AND u.origin = 'legacy' AND u.content_id IS NULL
  ) OR EXISTS (SELECT 1 FROM publication_operations WHERE content_id = NEW.content_id)
    THEN RAISE(ABORT, 'invalid_legacy_blog_link') END;
END;
CREATE TRIGGER claim_legacy_blog_url AFTER INSERT ON legacy_blog_links BEGIN
  UPDATE event_url_owners SET origin = 'cms', content_id = NEW.content_id
    WHERE slug = 'local-blog/' || (SELECT slug FROM legacy_blog_sources WHERE source_id = NEW.source_id);
END;
CREATE TRIGGER immutable_legacy_blog_link BEFORE UPDATE ON legacy_blog_links
BEGIN SELECT RAISE(ABORT, 'immutable_legacy_blog_link'); END;
CREATE TRIGGER retain_legacy_blog_link BEFORE DELETE ON legacy_blog_links
BEGIN SELECT RAISE(ABORT, 'retain_legacy_blog_link'); END;
CREATE TRIGGER immutable_legacy_blog_source BEFORE UPDATE ON legacy_blog_sources
BEGIN SELECT RAISE(ABORT, 'immutable_legacy_blog_source'); END;
CREATE TRIGGER retain_legacy_blog_source BEFORE DELETE ON legacy_blog_sources
BEGIN SELECT RAISE(ABORT, 'retain_legacy_blog_source'); END;
